{
  "id": "lead-reminder-workflow",
  "name": "Lead Reminder Email",
  "nodes": [
    {
      "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
      "name": "Webhook",
      "type": "n8n-nodes-base.webhook",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {
        "path": "lead",
        "httpMethod": "POST",
        "responseMode": "onReceived",
        "responseData": {
          "options": {}
        }
      }
    },
    {
      "id": "b2c3d4e5-f6a7-8901-bcde-f23456789012",
      "name": "Wait 24 Hours",
      "type": "n8n-nodes-base.wait",
      "typeVersion": 1,
      "position": [500, 300],
      "parameters": {
        "amount": 24,
        "unit": "hours"
      }
    },
    {
      "id": "c3d4e5f6-a7b8-9012-cdef-345678901234",
      "name": "Send Reminder Email",
      "type": "n8n-nodes-base.sendEmail",
      "typeVersion": 1,
      "position": [750, 300],
      "parameters": {
        "fromEmail": "noreply@example.com",
        "toEmail": "={{ $json.email }}",
        "subject": "Erinnerung: Ihr Lead wartet",
        "text": "Hallo {{ $json.name }},\n\ndies ist eine Erinnerung an Ihren Lead von vor 24 Stunden.\n\nDetails:\n- Name: {{ $json.name }}\n- E-Mail: {{ $json.email }}\n- Nachricht: {{ $json.message }}\n\nBitte kümmern Sie sich zeitnah darum.\n\nMit freundlichen Grüßen\nIhr Automatisierungssystem"
      }
    }
  ],
  "connections": {
    "Webhook": {
      "main": [
        [
          {
            "node": "Wait 24 Hours",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Wait 24 Hours": {
      "main": [
        [
          {
            "node": "Send Reminder Email",
            "type": "main",
            "index": 0
          }
        ]
      ]
    }
  }
}

{
  "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
  "name": "Google Sheets to Slack",
  "nodes": [
    {
      "id": "11111111-1111-1111-1111-111111111111",
      "name": "Google Sheets Trigger",
      "type": "n8n-nodes-base.googleSheetsTrigger",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {
        "spreadsheetId": "YOUR_SPREADSHEET_ID",
        "range": "Sheet1!A:Z",
        "pollTimes": {
          "item": [
            {
              "mode": "everyMinute"
            }
          ]
        }
      }
    },
    {
      "id": "22222222-2222-2222-2222-222222222222",
      "name": "Send Slack Message",
      "type": "n8n-nodes-base.slack",
      "typeVersion": 1,
      "position": [550, 300],
      "parameters": {
        "resource": "message",
        "operation": "post",
        "channel": "#team-channel",
        "text": "Neue Zeile in Google Sheets: {{ $json }}",
        "blocksUi": {
          "blocks": [
            {
              "type": "section",
              "text": {
                "type": "mrkdwn",
                "text": "📊 *Neue Zeile in Google Sheets erkannt*"
              }
            },
            {
              "type": "section",
              "fields": [
                {
                  "type": "mrkdwn",
                  "text": "*Daten:*\n{{ JSON.stringify($json, null, 2) }}"
                }
              ]
            }
          ]
        }
      }
    }
  ],
  "connections": {
    "Google Sheets Trigger": {
      "main": [
        [
          {
            "node": "Send Slack Message",
            "type": "main",
            "index": 0
          }
        ]
      ]
    }
  }
}

{
  "id": "weekly-api-to-airtable",
  "name": "Weekly API to Airtable",
  "nodes": [
    {
      "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
      "name": "Schedule Trigger",
      "type": "n8n-nodes-base.scheduleTrigger",
      "typeVersion": 1.1,
      "position": [250, 300],
      "parameters": {
        "rule": {
          "interval": [
            {
              "field": "cronExpression",
              "cronExpression": "0 9 * * 1"
            }
          ]
        }
      }
    },
    {
      "id": "b2c3d4e5-f6a7-8901-bcde-f23456789012",
      "name": "HTTP Request",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 4.1,
      "position": [500, 300],
      "parameters": {
        "method": "GET",
        "url": "https://api.example.com/data",
        "options": {}
      }
    },
    {
      "id": "c3d4e5f6-a7b8-9012-cdef-345678901234",
      "name": "Airtable",
      "type": "n8n-nodes-base.airtable",
      "typeVersion": 2,
      "position": [750, 300],
      "parameters": {
        "operation": "create",
        "baseId": "appXXXXXXXXXXXXXX",
        "tableId": "tblXXXXXXXXXXXXXX",
        "columns": {
          "mappingMode": "autoMapInputData"
        }
      }
    }
  ],
  "connections": {
    "Schedule Trigger": {
      "main": [[{"node": "HTTP Request", "type": "main", "index": 0}]]
    },
    "HTTP Request": {
      "main": [[{"node": "Airtable", "type": "main", "index": 0}]]
    }
  }
}

{
  "id": "webhook-urgent-email",
  "name": "Webhook Urgent Email",
  "nodes": [
    {
      "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
      "name": "Webhook",
      "type": "n8n-nodes-base.webhook",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {
        "httpMethod": "POST",
        "path": "urgent-check",
        "responseMode": "onReceived",
        "options": {}
      }
    },
    {
      "id": "b2c3d4e5-f6a7-8901-bcde-f23456789012",
      "name": "Check Status",
      "type": "n8n-nodes-base.if",
      "typeVersion": 1,
      "position": [500, 300],
      "parameters": {
        "conditions": {
          "string": [
            {
              "value1": "={{ $json[\"status\"] }}",
              "operation": "equal",
              "value2": "urgent"
            }
          ]
        }
      }
    },
    {
      "id": "c3d4e5f6-a7b8-9012-cdef-345678901234",
      "name": "Send Email",
      "type": "n8n-nodes-base.sendEmail",
      "typeVersion": 1,
      "position": [750, 200],
      "parameters": {
        "fromEmail": "noreply@example.com",
        "toEmail": "admin@example.com",
        "subject": "Urgent Alert Received",
        "text": "A webhook request with status 'urgent' was received.\n\nPayload: {{ JSON.stringify($json, null, 2) }}"
      }
    }
  ],
  "connections": {
    "Webhook": {
      "main": [
        [
          {
            "node": "Check Status",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Check Status": {
      "main": [
        [
          {
            "node": "Send Email",
            "type": "main",
            "index": 0
          }
        ],
        []
      ]
    }
  }
}

