{
  "id": "daily-airtable-export-email",
  "name": "Daily Airtable Export to Email",
  "nodes": [
    {
      "id": "1a2b3c4d-5e6f-7890-abcd-ef1234567890",
      "name": "Midnight Trigger",
      "type": "n8n-nodes-base.cron",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {
        "triggerTimes": {
          "item": [
            {
              "mode": "everyDay",
              "hour": 0,
              "minute": 0
            }
          ]
        }
      }
    },
    {
      "id": "2b3c4d5e-6f78-90ab-cdef-1234567890ab",
      "name": "Get Airtable Data",
      "type": "n8n-nodes-base.airtable",
      "typeVersion": 1,
      "position": [500, 300],
      "parameters": {
        "operation": "list",
        "baseId": "YOUR_BASE_ID",
        "tableId": "YOUR_TABLE_ID",
        "options": {
          "view": "Grid view"
        }
      }
    },
    {
      "id": "3c4d5e6f-7890-abcd-ef12-34567890abcd",
      "name": "Convert to CSV",
      "type": "n8n-nodes-base.convertToFile",
      "typeVersion": 1,
      "position": [750, 300],
      "parameters": {
        "from": "json",
        "options": {
          "fileName": "airtable-export-{{ $now.format('YYYY-MM-DD') }}.csv"
        }
      }
    },
    {
      "id": "4d5e6f78-90ab-cdef-1234-567890abcdef",
      "name": "Send Email",
      "type": "n8n-nodes-base.sendEmail",
      "typeVersion": 1,
      "position": [1000, 300],
      "parameters": {
        "fromEmail": "your-email@example.com",
        "toEmail": "recipient@example.com",
        "subject": "Daily Airtable Export - {{ $now.format('YYYY-MM-DD') }}",
        "text": "Please find attached the daily Airtable export.",
        "attachments": [
          {
            "binaryPropertyName": "data"
          }
        ]
      }
    }
  ],
  "connections": {
    "Midnight Trigger": {
      "main": [
        [
          {
            "node": "Get Airtable Data",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Get Airtable Data": {
      "main": [
        [
          {
            "node": "Convert to CSV",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Convert to CSV": {
      "main": [
        [
          {
            "node": "Send Email",
            "type": "main",
            "index": 0
          }
        ]
      ]
    }
  }
}

