{
  "id": "google-calendar-reminder-workflow",
  "name": "Google Calendar Event Reminder",
  "nodes": [
    {
      "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
      "name": "Google Calendar Trigger",
      "type": "n8n-nodes-base.googleCalendarTrigger",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {
        "calendar": "primary",
        "eventTypes": ["created"],
        "pollTimes": {
          "item": [
            {
              "mode": "everyHour"
            }
          ]
        }
      }
    },
    {
      "id": "b2c3d4e5-f6a7-8901-bcde-f23456789012",
      "name": "Wait Until 1 Day Before",
      "type": "n8n-nodes-base.wait",
      "typeVersion": 1,
      "position": [500, 300],
      "parameters": {
        "waitUntil": "={{$json.start.dateTime || $json.start.date}}",
        "offset": -86400000,
        "unit": "milliseconds"
      }
    },
    {
      "id": "c3d4e5f6-a7b8-9012-cdef-345678901234",
      "name": "Send Reminder Email",
      "type": "n8n-nodes-base.sendEmail",
      "typeVersion": 1,
      "position": [750, 300],
      "parameters": {
