{
  "id": "poll-api-status-change-slack",
  "name": "Poll API & Notify Slack on Status Change",
  "nodes": [
    {
      "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
      "name": "Every 15 Minutes",
      "type": "n8n-nodes-base.scheduleTrigger",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {
        "rule": {
          "interval": [
            {
              "field": "minutes",
              "minutesInterval": 15
            }
          ]
        }
      }
    },
    {
      "id": "b2c3d4e5-f6a7-8901-bcde-f23456789012",
      "name": "Fetch API Status",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 4,
      "position": [500, 300],
      "parameters": {
        "method": "GET",
        "url": "https://api.example.com/status",
        "options": {},
        "jsonParameters": true,
        "parameters": [],
        "authentication": "none"
      }
    },
    {
      "id": "c3d4e5f6-a7b8-9012-cdef-345678901234",
      "name": "Check Status Changed",
      "type": "n8n-nodes-base.if",
      "typeVersion": 1,
      "position": [750, 300],
      "parameters": {
        "conditions": {
          "string": [
            {
              "value1": "={{ $json.status }}",
              "operation": "notEqual",
              "value2": "={{ $workflow.staticData.lastStatus || '' }}"
            }
          ]
        }
      }
    },
    {
      "id": "d4e5f6a7-b8c9-0123-defg-456789012345",
      "name": "Update Stored Status",
      "type": "n8n-nodes-base.set",
      "typeVersion": 3,
      "position": [1000, 200],
      "parameters": {
        "keepOnlySet": true,
        "values": {
          "string": [
            {
              "name": "lastStatus",
              "value": "={{ $json.status }}"
            }
          ]
        },
        "options": {}
      }
    },
    {
      "id": "e5f6a7b8-c9d0-1234-efgh-567890123456",
      "name": "Send Slack Notification",
      "type": "n8n-nodes-base.slack",
      "typeVersion": 2,
      "position": [1000, 400],
      "parameters": {
        "resource": "message",
        "operation": "post",
        "channel": "#alerts",
        "text": "🚨 Status changed to: *{{ $json.status }}*",
        "options": {}
      }
    }
  ],
  "connections": {
    "Every 15 Minutes": {
      "main": [[{"node": "Fetch API Status", "type": "main", "index": 0}]]
    },
    "Fetch API Status": {
      "main": [[{"node": "Check Status Changed", "type": "main", "index": 0}]]
    },
    "Check Status Changed": {
      "main": [
        [
          {"node": "Update Stored Status", "type": "main", "index": 0},
          {"node": "Send Slack Notification", "type": "main", "index": 0}
        ],
        []
      ]
    }
  }
}

