      "parameters": {
        "jsCode": "const staticData = $getWorkflowStaticData('global');\nconst currentStatus = $input.first().json.status;\nconst previousStatus = staticData.lastStatus;\nconst changed = previousStatus !== undefined && previousStatus !== currentStatus;\nstaticData.lastStatus = currentStatus;\nreturn [{ json: { status: currentStatus, previousStatus: previousStatus !== undefined ? previousStatus : null, changed } }];"
      }
    },
